(function(){
  if (window.__relInstalled__) return;
  window.__relInstalled__ = true;
  var canvas = document.getElementById('relCanvas');
  var ctx = canvas.getContext('2d');
  var vtrainSlider = document.getElementById('vtrainSlider');
  var vtrainVal = document.getElementById('vtrainVal');
  var uSlider = document.getElementById('uSlider');
  var uVal = document.getElementById('uVal');
  var out = document.getElementById('relOut');
  var playBtn = document.getElementById('playBtn');
  var running = false, time = 0;
  var trail = [];
  window.simState = { vt: 8, u: 4, vAbs: 12, running: false, time: 0 };
  function arrow(x1, y1, x2, y2, color, lw){
    var dx = x2 - x1, dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len < 4) return;
    var ux = dx / len, uy = dy / len;
    ctx.strokeStyle = color; ctx.lineWidth = lw || 3;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2 - ux * 2, y2 - uy * 2); ctx.stroke();
    var ah = 8;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - ux * ah - uy * ah * 0.5, y2 - uy * ah + ux * ah * 0.5);
    ctx.lineTo(x2 - ux * ah + uy * ah * 0.5, y2 - uy * ah - ux * ah * 0.5);
    ctx.closePath(); ctx.fill();
  }
  function draw(){
    var vt = parseFloat(vtrainSlider.value);
    var u = parseFloat(uSlider.value);
    var vAbs = vt + u;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var GY = 240;
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, GY); ctx.lineTo(canvas.width, GY); ctx.stroke();
    ctx.fillStyle = '#64748b'; ctx.font = '12px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText('مراقب أرضي', 10, GY + 12);
    ctx.fillStyle = '#dc2626';
    ctx.beginPath(); ctx.arc(40, GY - 8, 8, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(34, GY, 12, 22);
    var trainW = 420, trainH = 56;
    var trainX = (time * vt * 7) % (canvas.width + trainW) - trainW;
    var trainY = GY - trainH - 40;
    ctx.fillStyle = '#e2e8f0';
    ctx.fillRect(trainX, trainY, trainW, trainH);
    ctx.strokeStyle = '#334155'; ctx.lineWidth = 2;
    ctx.strokeRect(trainX, trainY, trainW, trainH);
    ctx.fillStyle = '#334155';
    for (var i = 0; i < 3; i++) ctx.fillRect(trainX + 8 + i * 16, trainY + trainH - 14, 9, 12);
    var pw = trainX + 40 + (((time * u * 7) % Math.max(trainW - 80, 1)));
    var personY = trainY + trainH / 2;
    ctx.fillStyle = '#16a34a';
    ctx.beginPath(); ctx.arc(pw, personY - 10, 7, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(pw - 4, personY - 2, 8, 14);
    trail.push([pw, personY]);
    if (trail.length > 140) trail.shift();
    ctx.strokeStyle = 'rgba(22,163,74,0.35)'; ctx.lineWidth = 1.5;
    ctx.beginPath();
    for (var ti = 0; ti < trail.length; ti++) {
      if (ti === 0) ctx.moveTo(trail[ti][0], trail[ti][1]); else ctx.lineTo(trail[ti][0], trail[ti][1]);
    }
    ctx.stroke();
    var topY = 22;
    var vy = Math.max(6, Math.abs(vt) * 3);
    var uy2 = Math.max(5, Math.abs(u) * 3);
    var vyAbs = Math.max(6, Math.abs(vAbs) * 3);
    arrow(80, topY, 80 + vy, topY, '#dc2626');
    arrow(150, topY + 20, 150 + uy2, topY + 20, '#16a34a');
    arrow(220, topY + 40, 220 + vyAbs, topY + 40, '#2563eb');
    ctx.font = '12px sans-serif'; ctx.textBaseline = 'top';
    ctx.fillStyle = '#dc2626'; ctx.textAlign = 'left';
    ctx.fillText('vₚ (نسبة للأرض) = ' + vt + ' m/s', 90, topY - 2);
    ctx.fillStyle = '#16a34a';
    ctx.fillText('u (نسبة للقطار) = ' + (u > 0 ? '+' : '') + u + ' m/s', 160, topY + 18);
    ctx.fillStyle = '#2563eb';
    ctx.fillText('v (نسبة للأرض) = vₚ + u = ' + vAbs + ' m/s', 230, topY + 38);
    vtrainVal.textContent = vt;
    uVal.textContent = (u > 0 ? '+' : '') + u;
    out.textContent = vAbs < 0
      ? 'اتجاه حركة الشخص نسبةً للأرض عكس اتجاه القطار: v = ' + vAbs + ' m/s'
      : 'سرعة الشخص نسبةً للأرض v = vₚ + u = ' + vAbs + ' m/s';
    window.simState.vt = vt; window.simState.u = u; window.simState.vAbs = vAbs; window.simState.time = time;
  }
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل الحركة';
  });
  vtrainSlider.addEventListener('input', function(){ trail = []; });
  uSlider.addEventListener('input', function(){ trail = []; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){
    if (running) { time += 0.016; if (time > 30) time = 0; }
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
